"""Exact C136014 backing capture against an operator-owned CARLA world.

CPU --check validates the selected construction. Live motion and camera coverage
remain subject to original-source verification after an authorized capture.
"""
from __future__ import annotations
import argparse
import json
from math import hypot
from pathlib import Path

CASE_SUFFIX='__backing_interference_onset_grid-0000'

def check_config(config):
    if (config.get('law_id'),config.get('cell_id'),config.get('actor')) != ('NRS-484B-113-1','C136014','motor_vehicle_driver'):
        raise ValueError('wrong law/cell/actor for backing exact case')
    if not config.get('selected_case_id','').endswith(CASE_SUFFIX):
        raise ValueError('wrong selected backing case')
    if config.get('rate_hz')!=20 or config.get('frames')!=160 or len(config.get('cameras',[]))!=4:
        raise ValueError('exact 20 Hz four-camera duration contract missing')
    if config.get('case',{}).get('case_id')!=config['selected_case_id']:
        raise ValueError('case/config identity differs')
    return True

def choose_narrow_road(world_map):
    """Select one connected travel lane with room for reverse encounter."""
    for spawn in world_map.get_spawn_points():
        waypoint=world_map.get_waypoint(spawn.location)
        if waypoint is None or waypoint.is_junction or not 2.3<=waypoint.lane_width<=3.0:
            continue
        behind=waypoint.previous(18.0)
        ahead=waypoint.next(18.0)
        if len(behind)!=1 or len(ahead)!=1:
            continue
        rear,front=behind[0],ahead[0]
        if any(w.is_junction or w.road_id!=waypoint.road_id or w.lane_id!=waypoint.lane_id for w in (rear,front)):
            continue
        return {'ego':waypoint,'other':rear,'front':front,'lane_width_m':waypoint.lane_width}
    raise ValueError('No connected Native narrow-road 18 m reverse encounter')

def _spawn(world,blueprint_id,transform):
    actor=world.try_spawn_actor(world.get_blueprint_library().find(blueprint_id),transform)
    if actor is None:raise ValueError('Native actor spawn failed: '+blueprint_id)
    return actor

def _state(actor):
    loc=actor.get_transform().location;vel=actor.get_velocity()
    return {'actor_id':actor.id,'position_m':[loc.x,loc.y,loc.z],
            'speed_mps':hypot(vel.x,vel.y),'body_vertices_m':[
                [p.x,p.y,p.z] for p in actor.bounding_box.get_world_vertices(actor.get_transform())]}

def run(output,host,port):
    import carla
    from pipeline_capture import PipelineCapture
    from worker_exchange.native_output import FrameMap,seal_capture
    from backing_camera_capture import CAMERAS,FireCameraCapture,FFmpegSourceSink
    output=Path(output);config=json.loads((output/'config.json').read_text());check_config(config)
    client=carla.Client(host,port);client.set_timeout(30)
    world=client.get_world();original=world.get_settings();owned=[];sinks={};camera=None;pipeline=None;mapping=None;stream=None
    frames=[];failed=False;restored=False
    try:
        settings=world.get_settings();settings.synchronous_mode=True;settings.fixed_delta_seconds=.05;world.apply_settings(settings)
        route=choose_narrow_road(world.get_map())
        ego=_spawn(world,'vehicle.tesla.model3',route['ego'].transform);owned.append(ego)
        other=_spawn(world,'vehicle.audi.tt',route['other'].transform);owned.append(other)
        for name in CAMERAS:sinks[name]=FFmpegSourceSink(output,name)
        camera=FireCameraCapture(world,carla,ego,sinks)
        pipeline=PipelineCapture(client,ego,output,config['selected_case_id'],required_observations=config.get('required_atoms',[]))
        mapping=FrameMap(output/'video_frames.jsonl')
        stream=(output/'backing_history.jsonl').open('x',buffering=1)
        start=None
        for _ in range(config['frames']):
            ego.apply_control(carla.VehicleControl(throttle=.14,reverse=True,steer=0))
            other.apply_control(carla.VehicleControl(throttle=.16,steer=0) if len(frames)<40 else carla.VehicleControl(brake=.4,steer=0))
            frame=world.tick();snapshot=world.get_snapshot()
            if snapshot.frame!=frame:raise ValueError('Native snapshot/frame mismatch')
            if start is None:start=snapshot.timestamp.elapsed_seconds
            time_s=snapshot.timestamp.elapsed_seconds-start
            camera.wait_for_frame(frame)
            row=pipeline.capture(frame,time_s)
            if row.get('frame')!=frame or row.get('time_s')!=time_s:raise ValueError('Pipeline frame join differs')
            mapping.append(frame,time_s)
            stream.write(json.dumps({'frame':frame,'time_s':time_s,'ego':_state(ego),'other':_state(other),
                                     'ego_reverse_gear':bool(ego.get_control().reverse),
                                     'road_id':route['ego'].road_id,'lane_width_m':route['lane_width_m']})+'\n')
            frames.append(frame)
        camera.verify_frames(frames)
    except BaseException:
        failed=True;raise
    finally:
        if stream:stream.close()
        if mapping:mapping.close()
        if pipeline:pipeline.close(confirmed=not failed)
        if camera:camera.close()
        for sink in sinks.values():sink.close()
        for actor in reversed(owned):actor.destroy()
        world.apply_settings(original)
        current=world.get_settings();restored=(current.synchronous_mode==original.synchronous_mode and current.fixed_delta_seconds==original.fixed_delta_seconds)
        if not restored:raise ValueError('Native settings restoration readback differs')
    if not frames:raise ValueError('No Native backing frames')
    (output/'acquisition-provenance.json').write_text(json.dumps({'provenance_kind':'native','diagnostic_fixture':False,'original_frames':len(frames)})+'\n')
    seal_capture(output,frames=len(frames),restoration={'restored':restored},errors=[],
                 encoder_exit_codes={name:0 for name in CAMERAS},
                 context={'native_map_name':world.get_map().name,'road_id':route['ego'].road_id})

def main():
    p=argparse.ArgumentParser();p.add_argument('--check',action='store_true');p.add_argument('--output-dir');p.add_argument('--host',default='127.0.0.1');p.add_argument('--port',type=int,default=2000)
    a=p.parse_args()
    if a.check:
        check_config(json.loads(Path('config.json').read_text()))
        return
    if not a.output_dir:p.error('--output-dir required')
    run(a.output_dir,a.host,a.port)
if __name__=='__main__':main()

"""CPU scene request and original-motion observations for backing on a narrow road.

The measured clearance and other-traffic response do not decide reasonable safety.
"""
from __future__ import annotations
from math import hypot


def construct(adapter, *, other_traffic_mps, ego_reverse_mps):
    if other_traffic_mps < 0 or ego_reverse_mps <= 0:
        raise ValueError('invalid engineering speed request')
    road=adapter.road(layout='narrow_road',lanes=2,width_m=5.5)
    ego=adapter.vehicle(role='ego',route=[(20.0,0.0),(4.0,0.0)],gear='reverse',
                        target_mps=ego_reverse_mps)
    other=adapter.vehicle(role='other_traffic',route=[(0.0,0.0),(30.0,0.0)],
                          target_mps=other_traffic_mps)
    return {'road':road,'ego':ego,'other':other}


def measure(samples):
    if len(samples)<3:raise ValueError('original backing span too short')
    rows=[]
    for i,s in enumerate(samples):
        if s.get('frame')!=i or abs(s.get('time_s',-1)-i*.05)>.005:
            raise ValueError('non-20Hz ordered original frames')
        if not s.get('ego_source') or not s.get('other_source') or not s.get('road_source'):
            raise ValueError('original subject, traffic or road source missing')
        if s.get('ego_reverse_gear') is not True:
            raise ValueError('reverse gear readback absent')
        for key in ('ego_xy','other_xy'):
            p=s.get(key)
            if not isinstance(p,list) or len(p)!=2 or any(type(v) not in (int,float) for v in p):
                raise ValueError('original actor position missing')
        if any(type(s.get(k)) not in (int,float) or s[k]<0 for k in ('ego_speed_mps','other_speed_mps')):
            raise ValueError('original actor speed missing')
        rows.append({'frame':i,'ego_x':s['ego_xy'][0],
                     'center_distance_m':hypot(s['ego_xy'][0]-s['other_xy'][0],s['ego_xy'][1]-s['other_xy'][1]),
                     'ego_speed_mps':s['ego_speed_mps'],'other_speed_mps':s['other_speed_mps']})
    if rows[-1]['ego_x']>=rows[0]['ego_x']:
        raise ValueError('measured reverse displacement absent')
    return {'reverse_displacement_m':rows[0]['ego_x']-rows[-1]['ego_x'],
            'min_center_distance_m':min(r['center_distance_m'] for r in rows),
            'other_speed_change_mps':rows[-1]['other_speed_mps']-rows[0]['other_speed_mps'],
            'samples':rows,'legal_safety_judgment':None,'legal_interference_judgment':None}


def audit_comparison(a,b,variable):
    if variable not in ('traffic_clearance','other_traffic_response'):
        raise ValueError('unknown backing comparison')
    if not a.get('samples') or not b.get('samples'):
        raise ValueError('original backing measurements missing')
    for key in ('map_hash','road_hash','camera_plan_hash','duration_s','ego_reverse_mps','other_actor_hash'):
        if not a.get(key) or a[key]!=b.get(key):raise ValueError('fixed condition changed: '+key)
    if variable=='traffic_clearance':
        fixed,varied='other_speed_change_mps','min_center_distance_m'
    else:
        fixed,varied='min_center_distance_m','other_speed_change_mps'
    if abs(a[fixed]-b[fixed])>.001:raise ValueError('held traffic condition changed')
    if abs(a[varied]-b[varied])<.001:raise ValueError('deliberate measured difference absent')
    return {'comparison_complete':True,'fixed_conditions_checked':True,'legal_safety_judgment':None}

"""Four original-frame RGB sources for the fire-apparatus delivery attempt.

The caller owns the world and encoder sinks. Each sensor is attached to the
subject; a sink must retain its own unscaled source stream under the given name.
This module does not infer fire-alarm purpose or physical visibility from pixels.
"""
from __future__ import annotations

from dataclasses import dataclass
import subprocess
from pathlib import Path
from threading import Condition
from time import monotonic


CAMERAS = {
    "overview": ((-8.0, 0.0, 8.0), (-12.0, 0.0, 0.0), (1920, 1080), 95),
    "approach": ((1.2, 0.0, 2.0), (0.0, 0.0, 0.0), (1280, 720), 90),
    "reference_corner": ((-3.0, 2.5, 2.6), (-7.0, 0.0, 0.0), (1280, 720), 100),
    "driver_reference": ((0.6, -0.35, 1.6), (0.0, 0.0, 0.0), (1280, 720), 85),
}


@dataclass(frozen=True)
class CameraPlan:
    name: str
    location: tuple[float, float, float]
    rotation: tuple[float, float, float]
    size: tuple[int, int]
    fov: int


def plans():
    return [CameraPlan(name, *spec) for name, spec in CAMERAS.items()]


class FFmpegSourceSink:
    """Retain one lossless, original-resolution BGRA stream from CARLA images."""

    def __init__(self, output, name, *, popen=subprocess.Popen):
        if name not in CAMERAS:
            raise ValueError("Unknown source camera")
        path = Path(output) / (name + ".mkv")
        if path.exists():
            raise ValueError("Retain prior source stream; use a fresh attempt")
        width, height = CAMERAS[name][2]
        self.size = width * height * 4
        self.process = popen(["ffmpeg", "-nostdin", "-loglevel", "error", "-y",
                              "-f", "rawvideo", "-pixel_format", "bgra",
                              "-video_size", f"{width}x{height}", "-framerate", "20",
                              "-i", "pipe:0", "-an", "-c:v", "ffv1", str(path)],
                             stdin=subprocess.PIPE)
        self.closed = False

    def write(self, image):
        if self.closed:
            raise ValueError("Source stream already closed")
        raw = image.raw_data
        if len(raw) != self.size:
            raise ValueError("Source camera raw byte count changed")
        self.process.stdin.write(raw)

    def close(self):
        if not self.closed:
            self.closed = True
            self.process.stdin.close()
            if self.process.wait() != 0:
                raise ValueError("Source camera encoder failed")


class FireCameraCapture:
    def __init__(self, world, carla_module, subject, sinks):
        if set(sinks) != set(CAMERAS):
            raise ValueError("Exactly four named source-camera sinks are required")
        self.sensors = {}
        self.sinks = sinks
        self.frames = {name: set() for name in CAMERAS}
        self.condition = Condition()
        self.callback_errors = []
        self.closed = False
        library = world.get_blueprint_library()
        try:
            for plan in plans():
                bp = library.find("sensor.camera.rgb")
                for key, value in (("image_size_x", plan.size[0]),
                                   ("image_size_y", plan.size[1]),
                                   ("fov", plan.fov), ("sensor_tick", 0.05)):
                    bp.set_attribute(key, str(value))
                loc = carla_module.Location(*plan.location)
                pitch, yaw, roll = plan.rotation
                transform = carla_module.Transform(loc, carla_module.Rotation(pitch, yaw, roll))
                sensor = world.spawn_actor(bp, transform, attach_to=subject)
                self.sensors[plan.name] = sensor
                sensor.listen(lambda image, name=plan.name: self._on_frame(name, image))
        except BaseException:
            self.close()
            raise

    def _on_frame(self, name, image):
        with self.condition:
            if self.closed:
                return
            try:
                if image.frame in self.frames[name]:
                    raise ValueError("Duplicate original camera frame: " + name)
                expected = CAMERAS[name][2]
                if (image.width, image.height) != expected:
                    raise ValueError("Source camera dimensions changed: " + name)
                self.sinks[name].write(image)
                self.frames[name].add(image.frame)
            except BaseException as error:
                self.callback_errors.append(error)
                raise
            finally:
                self.condition.notify_all()

    def wait_for_frame(self, frame, timeout_s=10):
        """Join all original source pixels before writing that Native tick."""
        deadline = monotonic() + timeout_s
        with self.condition:
            while True:
                if self.callback_errors:
                    raise ValueError("Source camera callback failed") from self.callback_errors[0]
                if all(frame in rows for rows in self.frames.values()):
                    return
                remaining = deadline - monotonic()
                if remaining <= 0:
                    missing = sorted(name for name, rows in self.frames.items() if frame not in rows)
                    raise ValueError("Timed out waiting for source camera frame "
                                     + str(frame) + ": " + ", ".join(missing))
                self.condition.wait(remaining)

    def verify_frames(self, frames):
        if self.callback_errors:
            raise ValueError("Source camera callback failed") from self.callback_errors[0]
        expected = set(frames)
        if not expected:
            raise ValueError("No captured original frames")
        for name, observed in self.frames.items():
            if observed != expected:
                raise ValueError("Missing or extra source-camera frames: " + name)
        return {name: len(expected) for name in CAMERAS}

    def close(self):
        if not self.closed:
            self.closed = True
            for sensor in self.sensors.values():
                sensor.stop()
                sensor.destroy()

from __future__ import annotations
import importlib.util,json,unittest
from pathlib import Path
s=importlib.util.spec_from_file_location('reverse_runner',Path(__file__).resolve().parents[1]/'runner.py')
m=importlib.util.module_from_spec(s);s.loader.exec_module(m)
class Location:
 def __init__(self,x):self.x=x;self.y=0;self.z=0
class Transform:
 def __init__(self,x):self.location=Location(x)
class Waypoint:
 def __init__(self,x,width=2.8):self.transform=Transform(x);self.lane_width=width;self.is_junction=False;self.road_id=1;self.lane_id=-1
 def previous(self,d):return [Waypoint(self.transform.location.x-d,self.lane_width)]
 def next(self,d):return [Waypoint(self.transform.location.x+d,self.lane_width)]
class Map:
 def get_spawn_points(self):return [Transform(0)]
 def get_waypoint(self,location):return Waypoint(location.x)
class RunnerTests(unittest.TestCase):
 def test_selects_connected_narrow_lane_both_directions(self):
  scene=m.choose_narrow_road(Map())
  self.assertEqual(scene['other'].transform.location.x,-18)
  self.assertEqual(scene['front'].transform.location.x,18)
 def test_rejects_wide_lane(self):
  class Wide(Map):
   def get_waypoint(self,location):return Waypoint(location.x,3.5)
  with self.assertRaisesRegex(ValueError,'No connected Native narrow-road'):m.choose_narrow_road(Wide())
 def test_exact_config_and_lazy_carla(self):
  config=json.loads((Path(__file__).resolve().parents[1]/'config.json').read_text())
  self.assertTrue(m.check_config(config))
  config['cell_id']='different'
  with self.assertRaisesRegex(ValueError,'wrong law/cell/actor'):m.check_config(config)
if __name__=='__main__':unittest.main()
